"use client";

import React, { useCallback, useEffect, useRef, useState } from "react";
import { ScanRecipe } from "./CameraScan";
import FridgeCook from "./FridgeCook";
import ReportContent from "./ReportContent";
import CalendarGrid from "./CalendarGrid";
import ICloudSetup from "./ICloudSetup";
import { eventDays } from "./calendar-layout";
import { calendarReadOnlyHelp, calendarSourceBadge } from "./calendar-provenance";
